//! Unit types for dimension parsing.
//!
//! This module provides the [`Unit`] enum for representing and converting
//! between different measurement units used in PCB design.

use crate::coords::{Nm, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
use serde::{Deserialize, Serialize};
use std::str::FromStr;
use thiserror::Error;

/// A unit of measurement for PCB dimensions.
///
/// Used for parsing dimensions from the DSL and converting to internal
/// nanometer representation.
///
/// # Examples
///
/// ```
/// use cypcb_core::{Unit, Nm};
///
/// let unit = Unit::Mm;
/// let nm = unit.to_nm(10.0);
/// assert_eq!(nm.0, 10_000_000);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Unit {
    /// Millimeters (1 mm = 1,000,000 nm)
    Mm,
    /// Mils / thousandths of an inch (1 mil = 25,400 nm)
    Mil,
    /// Inches (1 inch = 25,400,000 nm)
    Inch,
    /// Nanometers (native unit)
    Nm,
}

impl Unit {
    /// Convert a value in this unit to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
    /// assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
    /// assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
    /// assert_eq!(Unit::Nm.to_nm(100.0).0, 100);
    /// ```
    #[inline]
    pub fn to_nm(self, value: f64) -> Nm {
        let nm = match self {
            Unit::Mm => (value * NM_PER_MM as f64).round() as i64,
            Unit::Mil => (value * NM_PER_MIL as f64).round() as i64,
            Unit::Inch => (value * NM_PER_INCH as f64).round() as i64,
            Unit::Nm => value.round() as i64,
        };
        Nm(nm)
    }

    /// Convert a nanometer value to this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::{Unit, Nm};
    ///
    /// let nm = Nm(1_000_000);
    /// assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);
    /// ```
    #[inline]
    pub fn from_nm(self, nm: Nm) -> f64 {
        match self {
            Unit::Mm => nm.0 as f64 / NM_PER_MM as f64,
            Unit::Mil => nm.0 as f64 / NM_PER_MIL as f64,
            Unit::Inch => nm.0 as f64 / NM_PER_INCH as f64,
            Unit::Nm => nm.0 as f64,
        }
    }

    /// Get the suffix string for this unit.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!(Unit::Mm.suffix(), "mm");
    /// assert_eq!(Unit::Mil.suffix(), "mil");
    /// ```
    pub const fn suffix(self) -> &'static str {
        match self {
            Unit::Mm => "mm",
            Unit::Mil => "mil",
            Unit::Inch => "in",
            Unit::Nm => "nm",
        }
    }

    /// Get the nanometers per unit.
    ///
    /// Returns 1 for nanometers.
    pub const fn nm_per_unit(self) -> i64 {
        match self {
            Unit::Mm => NM_PER_MM,
            Unit::Mil => NM_PER_MIL,
            Unit::Inch => NM_PER_INCH,
            Unit::Nm => 1,
        }
    }
}

impl Default for Unit {
    fn default() -> Self {
        Unit::Mm
    }
}

impl std::fmt::Display for Unit {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.suffix())
    }
}

/// Error type for unit parsing.
#[derive(Debug, Clone, Error, PartialEq, Eq)]
#[error("unknown unit: '{0}' (expected: mm, mil, in, nm)")]
pub struct ParseUnitError(pub String);

impl FromStr for Unit {
    type Err = ParseUnitError;

    /// Parse a unit from a string.
    ///
    /// Accepts: "mm", "mil", "in", "inch", "nm"
    /// Case-insensitive.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Unit;
    ///
    /// assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
    /// assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
    /// assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
    /// assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    ///
    /// // Case insensitive
    /// assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
    /// ```
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s.to_lowercase().as_str() {
            "mm" => Ok(Unit::Mm),
            "mil" | "mils" => Ok(Unit::Mil),
            "in" | "inch" | "inches" => Ok(Unit::Inch),
            "nm" => Ok(Unit::Nm),
            _ => Err(ParseUnitError(s.to_string())),
        }
    }
}

/// A dimension value with an associated unit.
///
/// This is useful for preserving the original unit in the source
/// while still being able to convert to nanometers.
#[derive(Debug, Clone, Copy, PartialEq, Serialize, Deserialize)]
pub struct Dimension {
    /// The numeric value in the original unit.
    pub value: f64,
    /// The unit of measurement.
    pub unit: Unit,
}

impl Dimension {
    /// Create a new dimension.
    pub const fn new(value: f64, unit: Unit) -> Self {
        Dimension { value, unit }
    }

    /// Create a dimension in millimeters.
    pub const fn mm(value: f64) -> Self {
        Dimension { value, unit: Unit::Mm }
    }

    /// Create a dimension in mils.
    pub const fn mil(value: f64) -> Self {
        Dimension { value, unit: Unit::Mil }
    }

    /// Create a dimension in inches.
    pub const fn inch(value: f64) -> Self {
        Dimension { value, unit: Unit::Inch }
    }

    /// Create a dimension in nanometers.
    pub const fn nm(value: f64) -> Self {
        Dimension { value, unit: Unit::Nm }
    }

    /// Convert this dimension to nanometers.
    pub fn to_nm(self) -> Nm {
        self.unit.to_nm(self.value)
    }
}

impl std::fmt::Display for Dimension {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}{}", self.value, self.unit)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_unit_to_nm() {
        assert_eq!(Unit::Mm.to_nm(1.0).0, 1_000_000);
        assert_eq!(Unit::Mil.to_nm(1.0).0, 25_400);
        assert_eq!(Unit::Inch.to_nm(1.0).0, 25_400_000);
        assert_eq!(Unit::Nm.to_nm(1.0).0, 1);
    }

    #[test]
    fn test_unit_from_nm() {
        let nm = Nm(1_000_000);
        assert!((Unit::Mm.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400);
        assert!((Unit::Mil.from_nm(nm) - 1.0).abs() < 1e-9);

        let nm = Nm(25_400_000);
        assert!((Unit::Inch.from_nm(nm) - 1.0).abs() < 1e-9);
    }

    #[test]
    fn test_unit_round_trip() {
        for unit in [Unit::Mm, Unit::Mil, Unit::Inch] {
            let original = 10.5;
            let nm = unit.to_nm(original);
            let back = unit.from_nm(nm);
            assert!((back - original).abs() < 0.001, "Round-trip failed for {:?}", unit);
        }
    }

    #[test]
    fn test_unit_parse() {
        assert_eq!("mm".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("MM".parse::<Unit>().unwrap(), Unit::Mm);
        assert_eq!("mil".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("mils".parse::<Unit>().unwrap(), Unit::Mil);
        assert_eq!("in".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inch".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("inches".parse::<Unit>().unwrap(), Unit::Inch);
        assert_eq!("nm".parse::<Unit>().unwrap(), Unit::Nm);
    }

    #[test]
    fn test_unit_parse_error() {
        let result = "cm".parse::<Unit>();
        assert!(result.is_err());
        assert_eq!(result.unwrap_err().0, "cm");
    }

    #[test]
    fn test_dimension_to_nm() {
        let dim = Dimension::mm(10.0);
        assert_eq!(dim.to_nm().0, 10_000_000);

        let dim = Dimension::mil(100.0);
        assert_eq!(dim.to_nm().0, 2_540_000);
    }

    #[test]
    fn test_unit_suffix() {
        assert_eq!(Unit::Mm.suffix(), "mm");
        assert_eq!(Unit::Mil.suffix(), "mil");
        assert_eq!(Unit::Inch.suffix(), "in");
        assert_eq!(Unit::Nm.suffix(), "nm");
    }
}

//! CodeYourPCB Core
//!
//! Shared types, coordinates, and geometry primitives for the CodeYourPCB system.
//! All coordinates use integer nanometers (i64) for deterministic precision.
//!
//! # Why Integer Nanometers?
//!
//! PCB tools commonly face issues with floating-point accumulation errors.
//! Small precision errors compound across complex routing operations, leading to:
//! - Traces that should connect but don't (off by sub-micron amounts)
//! - Non-deterministic DRC results
//! - Different output from the same input file
//!
//! By using i64 nanometers internally:
//! - All coordinate arithmetic is exact
//! - Same input always produces identical output
//! - Comparisons and hashing are reliable
//! - Range is sufficient (i64 max = ~9.2 billion meters)
//!
//! # Coordinate System
//!
//! - Origin: bottom-left of the board
//! - X-axis: positive right
//! - Y-axis: positive up (mathematical convention)
//!
//! This matches standard mathematical conventions and most Gerber viewers.
//!
//! # Unit Conversions
//!
//! | Unit | Nanometers |
//! |------|------------|
//! | 1 mm | 1,000,000 |
//! | 1 mil | 25,400 |
//! | 1 inch | 25,400,000 |
//!
//! # Modules
//!
//! - [`coords`]: Core coordinate types ([`Nm`], [`Point`])
//! - [`units`]: Unit parsing and conversion ([`Unit`])
//! - [`geometry`]: Geometric primitives ([`Rect`])

pub mod coords;
pub mod geometry;
pub mod units;

// Re-export primary types at crate root for convenience
pub use coords::{Nm, Point, NM_PER_INCH, NM_PER_MIL, NM_PER_MM};
pub use geometry::Rect;
pub use units::{Dimension, ParseUnitError, Unit};

//! Coordinate types for PCB layout.
//!
//! All coordinates are stored internally as nanometers using i64. This provides:
//! - Deterministic precision (no floating-point accumulation errors)
//! - Sufficient range (i64 max = ~9.2 billion meters, more than enough for any PCB)
//! - Efficient comparison and hashing
//!
//! # Coordinate System
//!
//! The coordinate system uses:
//! - Origin: bottom-left of the board
//! - X-axis: positive right
//! - Y-axis: positive up (mathematical convention)
//!
//! # Unit Conversions
//!
//! - 1 mm = 1,000,000 nm
//! - 1 mil = 25,400 nm
//! - 1 inch = 25,400,000 nm

use serde::{Deserialize, Serialize};
use std::hash::Hash;
use std::ops::{Add, Div, Mul, Neg, Sub};

/// Conversion constant: nanometers per millimeter
pub const NM_PER_MM: i64 = 1_000_000;

/// Conversion constant: nanometers per mil (thousandth of an inch)
pub const NM_PER_MIL: i64 = 25_400;

/// Conversion constant: nanometers per inch
pub const NM_PER_INCH: i64 = 25_400_000;

/// A coordinate value in nanometers.
///
/// This newtype provides type safety and prevents accidentally mixing
/// different unit systems. All internal PCB coordinates use this type.
///
/// # Examples
///
/// ```
/// use cypcb_core::Nm;
///
/// let distance = Nm::from_mm(10.5);
/// assert_eq!(distance.0, 10_500_000);
///
/// let in_mm = distance.to_mm();
/// assert!((in_mm - 10.5).abs() < 1e-6);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, PartialOrd, Ord, Serialize, Deserialize)]
pub struct Nm(pub i64);

impl Nm {
    /// Zero nanometers.
    pub const ZERO: Nm = Nm(0);

    /// Maximum representable value.
    pub const MAX: Nm = Nm(i64::MAX);

    /// Minimum representable value.
    pub const MIN: Nm = Nm(i64::MIN);

    /// Create a new Nm value from raw nanometers.
    #[inline]
    pub const fn new(nm: i64) -> Self {
        Nm(nm)
    }

    /// Convert from millimeters to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Nm;
    ///
    /// let nm = Nm::from_mm(1.0);
    /// assert_eq!(nm.0, 1_000_000);
    /// ```
    #[inline]
    pub fn from_mm(mm: f64) -> Self {
        Nm((mm * NM_PER_MM as f64).round() as i64)
    }

    /// Convert from mils (thousandths of an inch) to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Nm;
    ///
    /// let nm = Nm::from_mil(1.0);
    /// assert_eq!(nm.0, 25_400);
    /// ```
    #[inline]
    pub fn from_mil(mil: f64) -> Self {
        Nm((mil * NM_PER_MIL as f64).round() as i64)
    }

    /// Convert from inches to nanometers.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Nm;
    ///
    /// let nm = Nm::from_inch(1.0);
    /// assert_eq!(nm.0, 25_400_000);
    /// ```
    #[inline]
    pub fn from_inch(inch: f64) -> Self {
        Nm((inch * NM_PER_INCH as f64).round() as i64)
    }

    /// Convert to millimeters.
    #[inline]
    pub fn to_mm(self) -> f64 {
        self.0 as f64 / NM_PER_MM as f64
    }

    /// Convert to mils (thousandths of an inch).
    #[inline]
    pub fn to_mil(self) -> f64 {
        self.0 as f64 / NM_PER_MIL as f64
    }

    /// Convert to inches.
    #[inline]
    pub fn to_inch(self) -> f64 {
        self.0 as f64 / NM_PER_INCH as f64
    }

    /// Get the absolute value.
    #[inline]
    pub fn abs(self) -> Self {
        Nm(self.0.abs())
    }

    /// Get the raw nanometer value.
    #[inline]
    pub const fn raw(self) -> i64 {
        self.0
    }
}

impl Add for Nm {
    type Output = Nm;

    #[inline]
    fn add(self, rhs: Nm) -> Nm {
        Nm(self.0 + rhs.0)
    }
}

impl Sub for Nm {
    type Output = Nm;

    #[inline]
    fn sub(self, rhs: Nm) -> Nm {
        Nm(self.0 - rhs.0)
    }
}

impl Mul<i64> for Nm {
    type Output = Nm;

    #[inline]
    fn mul(self, rhs: i64) -> Nm {
        Nm(self.0 * rhs)
    }
}

impl Div<i64> for Nm {
    type Output = Nm;

    #[inline]
    fn div(self, rhs: i64) -> Nm {
        Nm(self.0 / rhs)
    }
}

impl Neg for Nm {
    type Output = Nm;

    #[inline]
    fn neg(self) -> Nm {
        Nm(-self.0)
    }
}

impl std::fmt::Display for Nm {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}nm", self.0)
    }
}

/// A 2D point in nanometers.
///
/// Represents a position on the PCB with integer precision.
/// Origin is at the bottom-left of the board, Y increases upward.
///
/// # Examples
///
/// ```
/// use cypcb_core::{Point, Nm};
///
/// let p = Point::from_mm(10.0, 20.0);
/// assert_eq!(p.x.0, 10_000_000);
/// assert_eq!(p.y.0, 20_000_000);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Default, Serialize, Deserialize)]
pub struct Point {
    /// X coordinate in nanometers (positive right).
    pub x: Nm,
    /// Y coordinate in nanometers (positive up).
    pub y: Nm,
}

impl Point {
    /// Origin point (0, 0).
    pub const ORIGIN: Point = Point { x: Nm::ZERO, y: Nm::ZERO };

    /// Create a new point from Nm values.
    #[inline]
    pub const fn new(x: Nm, y: Nm) -> Self {
        Point { x, y }
    }

    /// Create a point from raw nanometer values.
    #[inline]
    pub const fn from_raw(x: i64, y: i64) -> Self {
        Point { x: Nm(x), y: Nm(y) }
    }

    /// Create a point from millimeters.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Point;
    ///
    /// let p = Point::from_mm(1.0, 2.0);
    /// assert_eq!(p.x.0, 1_000_000);
    /// assert_eq!(p.y.0, 2_000_000);
    /// ```
    #[inline]
    pub fn from_mm(x: f64, y: f64) -> Self {
        Point {
            x: Nm::from_mm(x),
            y: Nm::from_mm(y),
        }
    }

    /// Create a point from mils.
    #[inline]
    pub fn from_mil(x: f64, y: f64) -> Self {
        Point {
            x: Nm::from_mil(x),
            y: Nm::from_mil(y),
        }
    }

    /// Create a point from inches.
    #[inline]
    pub fn from_inch(x: f64, y: f64) -> Self {
        Point {
            x: Nm::from_inch(x),
            y: Nm::from_inch(y),
        }
    }

    /// Calculate the squared distance to another point.
    ///
    /// Uses i128 for the intermediate calculation to avoid overflow
    /// when dealing with large coordinates.
    ///
    /// Returns the squared distance to avoid the cost of sqrt.
    /// Use this for distance comparisons.
    ///
    /// # Examples
    ///
    /// ```
    /// use cypcb_core::Point;
    ///
    /// let p1 = Point::from_mm(0.0, 0.0);
    /// let p2 = Point::from_mm(3.0, 4.0);
    ///
    /// // 3^2 + 4^2 = 25 (in mm), which is 25 * 10^12 in nm^2
    /// let dist_sq = p1.distance_squared(p2);
    /// assert_eq!(dist_sq, 25_000_000_000_000i128);
    /// ```
    #[inline]
    pub fn distance_squared(self, other: Point) -> i128 {
        let dx = (self.x.0 - other.x.0) as i128;
        let dy = (self.y.0 - other.y.0) as i128;
        dx * dx + dy * dy
    }

    /// Calculate the Manhattan distance to another point.
    ///
    /// This is |dx| + |dy|, useful for grid-based routing.
    #[inline]
    pub fn manhattan_distance(self, other: Point) -> Nm {
        let dx = (self.x.0 - other.x.0).abs();
        let dy = (self.y.0 - other.y.0).abs();
        Nm(dx + dy)
    }

    /// Add an offset to this point.
    #[inline]
    pub fn offset(self, dx: Nm, dy: Nm) -> Self {
        Point {
            x: Nm(self.x.0 + dx.0),
            y: Nm(self.y.0 + dy.0),
        }
    }
}

impl Add for Point {
    type Output = Point;

    #[inline]
    fn add(self, rhs: Point) -> Point {
        Point {
            x: self.x + rhs.x,
            y: self.y + rhs.y,
        }
    }
}

impl Sub for Point {
    type Output = Point;

    #[inline]
    fn sub(self, rhs: Point) -> Point {
        Point {
            x: self.x - rhs.x,
            y: self.y - rhs.y,
        }
    }
}

impl std::fmt::Display for Point {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "({}, {})", self.x, self.y)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_nm_from_mm() {
        assert_eq!(Nm::from_mm(1.0).0, 1_000_000);
        assert_eq!(Nm::from_mm(0.5).0, 500_000);
        assert_eq!(Nm::from_mm(0.001).0, 1_000);
    }

    #[test]
    fn test_nm_from_mil() {
        assert_eq!(Nm::from_mil(1.0).0, 25_400);
        assert_eq!(Nm::from_mil(10.0).0, 254_000);
    }

    #[test]
    fn test_nm_from_inch() {
        assert_eq!(Nm::from_inch(1.0).0, 25_400_000);
        assert_eq!(Nm::from_inch(0.1).0, 2_540_000);
    }

    #[test]
    fn test_nm_round_trip_mm() {
        let original = 10.5;
        let nm = Nm::from_mm(original);
        let back = nm.to_mm();
        assert!((back - original).abs() < 1e-6);
    }

    #[test]
    fn test_nm_round_trip_mil() {
        let original = 100.0;
        let nm = Nm::from_mil(original);
        let back = nm.to_mil();
        assert!((back - original).abs() < 1e-6);
    }

    #[test]
    fn test_nm_round_trip_inch() {
        let original = 2.5;
        let nm = Nm::from_inch(original);
        let back = nm.to_inch();
        assert!((back - original).abs() < 1e-6);
    }

    #[test]
    fn test_nm_arithmetic() {
        let a = Nm(100);
        let b = Nm(50);

        assert_eq!(a + b, Nm(150));
        assert_eq!(a - b, Nm(50));
        assert_eq!(a * 2, Nm(200));
        assert_eq!(a / 2, Nm(50));
        assert_eq!(-a, Nm(-100));
    }

    #[test]
    fn test_point_from_mm() {
        let p = Point::from_mm(1.0, 2.0);
        assert_eq!(p.x, Nm(1_000_000));
        assert_eq!(p.y, Nm(2_000_000));
    }

    #[test]
    fn test_point_distance_squared() {
        let p1 = Point::from_mm(0.0, 0.0);
        let p2 = Point::from_mm(3.0, 4.0);

        // 3^2 + 4^2 = 25 mm^2 = 25 * 10^12 nm^2
        let dist_sq = p1.distance_squared(p2);
        assert_eq!(dist_sq, 25_000_000_000_000i128);
    }

    #[test]
    fn test_point_manhattan_distance() {
        let p1 = Point::from_mm(0.0, 0.0);
        let p2 = Point::from_mm(3.0, 4.0);

        // |3| + |4| = 7 mm = 7,000,000 nm
        let dist = p1.manhattan_distance(p2);
        assert_eq!(dist, Nm(7_000_000));
    }

    #[test]
    fn test_conversion_constants() {
        // 1 inch = 25.4 mm
        assert_eq!(NM_PER_INCH, 25_400_000);

        // 1 mil = 0.001 inch = 0.0254 mm
        assert_eq!(NM_PER_MIL, 25_400);

        // 1 mm = 1,000,000 nm
        assert_eq!(NM_PER_MM, 1_000_000);

        // Verify relationship: 1 inch = 1000 mils
        assert_eq!(NM_PER_INCH, NM_PER_MIL * 1000);

        // Verify relationship: 1 inch = 25.4 mm
        assert_eq!(NM_PER_INCH, (NM_PER_MM as f64 * 25.4) as i64);
    }
}

//! Physical components for board entities.
//!
//! These components represent the physical properties of PCB elements:
//! layers, footprints, and pads.

use bevy_ecs::prelude::*;
use cypcb_core::Nm;
use serde::{Deserialize, Serialize};

/// PCB layer identifier.
///
/// Supports 2-32 layer boards as per BRD-02 requirement.
/// Layer numbering follows standard PCB conventions.
///
/// # Layer Types
///
/// - **Copper layers**: Conductive layers for traces and planes
/// - **Silkscreen**: Component markings (top/bottom)
/// - **Soldermask**: Solder mask openings (top/bottom)
/// - **Solderpaste**: Paste stencil openings (top/bottom)
/// - **Outline**: Board edge definition
///
/// # Examples
///
/// ```
/// use cypcb_world::Layer;
///
/// let top = Layer::TopCopper;
/// let bottom = Layer::BottomCopper;
/// let inner = Layer::Inner(1);
///
/// assert!(top.is_copper());
/// assert!(inner.is_copper());
/// assert!(!Layer::TopSilk.is_copper());
/// ```
#[derive(Component, Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
