//! PCB design constraints covering all fabrication parameters.
//!
//! [`DesignConstraints`] is the central configuration struct that defines the
//! manufacturing limits and design rules for a PCB. All dimension fields use
//! [`Nm`] for type-safe, integer-precision measurements.
//!
//! The [`Default`] implementation provides values matching JLCPCB's 2-layer
//! standard process capabilities.

use cypcb_core::Nm;
use serde::{Deserialize, Serialize};

/// Comprehensive PCB design constraints.
///
/// Organized by category:
/// - **Basic geometry**: fundamental clearances and minimums
/// - **Advanced geometry**: via details, drill aspect ratios, solder mask
/// - **Signal integrity**: impedance, differential pairs, length matching
/// - **Thermal**: current capacity, thermal relief, copper pour
/// - **Manufacturing**: board construction, hole spacing, via types
///
/// All dimension fields use [`Nm`]. Non-dimension fields (impedance in ohms,
/// ratios, weights) use appropriate numeric types.
///
/// # Examples
///
/// ```
/// use cypcb_rules::DesignConstraints;
/// use cypcb_core::Nm;
///
/// let dc = DesignConstraints::default();
/// // JLCPCB 2-layer minimum trace width: 0.127mm (5 mil)
/// assert_eq!(dc.min_trace_width, Nm::from_mm(0.127));
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesignConstraints {
    // ── Basic geometry ──────────────────────────────────────────────

    /// Minimum clearance between copper features on the same layer.
    pub min_clearance: Nm,
    /// Minimum trace (track) width.
    pub min_trace_width: Nm,
    /// Minimum finished drill hole diameter.
    pub min_drill_size: Nm,
    /// Minimum via drill hole diameter.
    pub min_via_drill: Nm,
    /// Minimum annular ring around pads.
    pub min_annular_ring: Nm,
    /// Minimum silkscreen line width.
    pub min_silk_width: Nm,
    /// Minimum clearance from copper to board edge.
    pub min_edge_clearance: Nm,

    // ── Advanced geometry ───────────────────────────────────────────

    /// Minimum annular ring around vias (may differ from pad annular ring).
    pub min_via_annular_ring: Nm,
    /// Maximum drill aspect ratio (depth:diameter). Stored as ratio × 100
    /// to keep integer precision (e.g. 600 = 6.0:1).
    pub max_drill_aspect_ratio: u32,
    /// Minimum solder mask bridge (dam) between adjacent mask openings.
    pub min_solder_mask_bridge: Nm,
    /// Minimum clearance between paste stencil openings.
    pub min_paste_clearance: Nm,
    /// Solder mask expansion beyond the pad.
    pub solder_mask_expansion: Nm,
    /// Minimum pad size (diameter for round, short axis for oblong).
    pub min_pad_size: Nm,
    /// Minimum copper-to-slot clearance.
    pub min_slot_clearance: Nm,

    // ── Signal integrity ────────────────────────────────────────────

    /// Default target impedance (ohms × 100 for integer precision, e.g. 5000 = 50.00 Ω).
    pub default_impedance_ohms_x100: u32,
    /// Differential pair gap (space between traces).
    pub diff_pair_gap: Nm,
    /// Differential pair width tolerance.
    pub diff_pair_tolerance: Nm,
    /// Maximum stub length for high-speed signals.
    pub max_stub_length: Nm,
    /// Length-matching tolerance for matched-length groups.
    pub length_match_tolerance: Nm,
    /// Maximum allowed via count in a high-speed signal path.
    pub max_vias_per_high_speed_net: u32,

    // ── Thermal ─────────────────────────────────────────────────────

    /// Maximum current per unit width (mA per mm × 100, e.g. 100_000 = 1000.00 mA/mm).
    /// Based on IPC-2152 for 10°C rise, 1oz copper, outer layer.
    pub max_current_per_width_x100: u32,
    /// Thermal relief gap width.
    pub thermal_relief_gap: Nm,
    /// Thermal relief spoke width.
    pub thermal_relief_spoke_width: Nm,
    /// Minimum clearance between copper pour and other copper features.
    pub min_copper_pour_clearance: Nm,
    /// Number of thermal relief spokes (typically 2 or 4).
    pub thermal_relief_spokes: u8,

    // ── Manufacturing ───────────────────────────────────────────────

    /// Copper weight in oz/ft² × 10 (e.g. 10 = 1.0 oz).
    pub copper_weight_oz_x10: u32,
    /// Total board thickness.
    pub board_thickness: Nm,
    /// Minimum hole-to-hole spacing (edge to edge).
    pub min_hole_to_hole: Nm,
    /// Minimum hole-to-board-edge spacing.
    pub min_hole_to_edge: Nm,
    /// Whether blind vias are allowed in this design.
    pub blind_vias_allowed: bool,
    /// Whether buried vias are allowed in this design.
    pub buried_vias_allowed: bool,
    /// Minimum copper feature size for acid trap avoidance.
    pub min_acid_trap: Nm,
    /// Maximum number of copper layers supported.
    pub max_copper_layers: u8,
    /// Whether castellated holes are allowed.
    pub castellated_holes_allowed: bool,
}

impl DesignConstraints {
    /// Number of constraint fields in the struct.
    /// Used for verification that the struct has 30+ fields.
    pub const FIELD_COUNT: usize = 35;
}

impl Default for DesignConstraints {
    /// JLCPCB 2-layer standard process defaults.
    ///
    /// Source: JLCPCB capabilities page (2-layer, standard process).
    /// Values represent minimum capabilities, not recommended values.
    fn default() -> Self {
        Self {
            // Basic geometry
            min_clearance: Nm::from_mm(0.127),            // 5 mil
            min_trace_width: Nm::from_mm(0.127),           // 5 mil
            min_drill_size: Nm::from_mm(0.3),              // 0.3mm min drill
            min_via_drill: Nm::from_mm(0.3),               // 0.3mm min via drill
            min_annular_ring: Nm::from_mm(0.127),          // 5 mil
            min_silk_width: Nm::from_mm(0.15),             // 0.15mm silk
            min_edge_clearance: Nm::from_mm(0.3),          // 0.3mm to edge

            // Advanced geometry
            min_via_annular_ring: Nm::from_mm(0.127),      // 5 mil
            max_drill_aspect_ratio: 800,                    // 8:1
            min_solder_mask_bridge: Nm::from_mm(0.1),      // 0.1mm
            min_paste_clearance: Nm::from_mm(0.127),       // 5 mil
            solder_mask_expansion: Nm::from_mm(0.05),      // 0.05mm typical
            min_pad_size: Nm::from_mm(0.5),                // 0.5mm min pad
            min_slot_clearance: Nm::from_mm(0.3),          // 0.3mm

            // Signal integrity
            default_impedance_ohms_x100: 5000,              // 50.00 Ω
            diff_pair_gap: Nm::from_mm(0.127),             // 5 mil
            diff_pair_tolerance: Nm::from_mm(0.025),       // 25µm
            max_stub_length: Nm::from_mm(1.0),             // 1mm
            length_match_tolerance: Nm::from_mm(0.5),      // 0.5mm
            max_vias_per_high_speed_net: 4,

            // Thermal
            max_current_per_width_x100: 100_000,            // 1000 mA/mm
            thermal_relief_gap: Nm::from_mm(0.254),        // 10 mil
            thermal_relief_spoke_width: Nm::from_mm(0.254), // 10 mil
            min_copper_pour_clearance: Nm::from_mm(0.254), // 10 mil
            thermal_relief_spokes: 4,

            // Manufacturing
            copper_weight_oz_x10: 10,                       // 1.0 oz
            board_thickness: Nm::from_mm(1.6),             // 1.6mm standard
            min_hole_to_hole: Nm::from_mm(0.5),            // 0.5mm
            min_hole_to_edge: Nm::from_mm(0.3),            // 0.3mm
            blind_vias_allowed: false,
            buried_vias_allowed: false,
            min_acid_trap: Nm::from_mm(0.127),             // 5 mil
            max_copper_layers: 2,
            castellated_holes_allowed: false,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_default_has_jlcpcb_values() {
        let dc = DesignConstraints::default();

        // JLCPCB 2-layer: 5mil min trace
        assert_eq!(dc.min_trace_width, Nm::from_mm(0.127));
        // JLCPCB 2-layer: 5mil min clearance
        assert_eq!(dc.min_clearance, Nm::from_mm(0.127));
        // Standard board thickness
        assert_eq!(dc.board_thickness, Nm::from_mm(1.6));
        // 1oz copper
        assert_eq!(dc.copper_weight_oz_x10, 10);
        // No blind/buried vias on 2-layer
        assert!(!dc.blind_vias_allowed);
        assert!(!dc.buried_vias_allowed);
        // 2 copper layers
        assert_eq!(dc.max_copper_layers, 2);
    }

    #[test]
    fn test_default_drill_sizes() {
        let dc = DesignConstraints::default();
        assert_eq!(dc.min_drill_size, Nm::from_mm(0.3));
        assert_eq!(dc.min_via_drill, Nm::from_mm(0.3));
    }

    #[test]
    fn test_field_count_at_least_30() {
        // Compile-time verified: DesignConstraints::FIELD_COUNT = 35
        assert!(DesignConstraints::FIELD_COUNT >= 30);
    }

    #[test]
    fn test_constraints_clone_eq() {
        let dc1 = DesignConstraints::default();
        let dc2 = dc1.clone();
        assert_eq!(dc1, dc2);
    }

    #[test]
    fn test_all_dimensions_use_nm() {
        let dc = DesignConstraints::default();
        // Spot-check that dimension fields are Nm, not raw numbers.
        // If any of these fail to compile, a field was changed away from Nm.
        let _: Nm = dc.min_clearance;
        let _: Nm = dc.min_trace_width;
        let _: Nm = dc.min_drill_size;
        let _: Nm = dc.min_via_drill;
        let _: Nm = dc.min_annular_ring;
        let _: Nm = dc.min_silk_width;
        let _: Nm = dc.min_edge_clearance;
        let _: Nm = dc.thermal_relief_gap;
        let _: Nm = dc.board_thickness;
        let _: Nm = dc.diff_pair_gap;
        let _: Nm = dc.length_match_tolerance;
    }

    #[test]
    fn test_constraints_serde_roundtrip() {
        let dc = DesignConstraints::default();
        let json = serde_json::to_string(&dc).unwrap();
        let dc2: DesignConstraints = serde_json::from_str(&json).unwrap();
        assert_eq!(dc, dc2);
    }

    #[test]
    fn test_edge_clearance_positive() {
        let dc = DesignConstraints::default();
        assert!(dc.min_edge_clearance.raw() > 0);
        assert!(dc.min_hole_to_edge.raw() > 0);
    }
}

//! Signal classification and per-class constraint overrides.
//!
//! Signals on a PCB are categorized by their electrical characteristics.
//! Each [`SignalClass`] maps to a [`SignalClassConstraints`] providing
//! per-class design rule overrides that take precedence over the base
//! [`DesignConstraints`].

use cypcb_core::Nm;
use serde::{Deserialize, Serialize};

/// Signal classification for PCB nets.
///
/// Each net in a design is assigned a signal class that determines
/// the routing rules and constraints applied to it.
///
/// # Examples
///
/// ```
/// use cypcb_rules::SignalClass;
///
/// let class = SignalClass::HighSpeed;
/// let constraints = class.default_constraints();
/// assert!(constraints.min_trace_width.raw() > 0);
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum SignalClass {
    /// Standard digital signals (GPIO, chip select, reset, etc.).
    Digital,
    /// High-speed digital signals (USB, HDMI, PCIe, DDR clocks, etc.).
    /// Requires controlled impedance, length matching, and stub limits.
    HighSpeed,
    /// Analog signals (ADC/DAC, sensor inputs, audio, etc.).
    /// Requires wider clearances and guard traces.
    Analog,
    /// Power distribution (VCC, GND, voltage rails).
    /// Requires wider traces for current capacity.
    Power,
    /// Differential pair signals (USB data, LVDS, Ethernet, etc.).
    /// Requires matched impedance, tight gap control, and length matching.
    Differential,
}

impl SignalClass {
    /// Returns all signal class variants.
    pub const ALL: [SignalClass; 5] = [
        SignalClass::Digital,
        SignalClass::HighSpeed,
        SignalClass::Analog,
        SignalClass::Power,
        SignalClass::Differential,
    ];

    /// Return default constraints for this signal class.
    ///
    /// These are sensible defaults based on IPC standards and common
    /// PCB design practice. Override per-project as needed.
    pub fn default_constraints(self) -> SignalClassConstraints {
        match self {
            SignalClass::Digital => SignalClassConstraints {
                min_trace_width: Nm::from_mm(0.15),      // 6 mil — comfortable digital
                min_clearance: Nm::from_mm(0.15),         // 6 mil
                preferred_layers: Vec::new(),              // any copper layer
                require_impedance_control: false,
                require_length_matching: false,
                require_diff_pair: false,
                max_stub_length: None,
                guard_trace_clearance: None,
            },
            SignalClass::HighSpeed => SignalClassConstraints {
                min_trace_width: Nm::from_mm(0.127),      // 5 mil — controlled impedance
                min_clearance: Nm::from_mm(0.2),           // 8 mil — extra clearance
                preferred_layers: vec![0, 2],              // outer + inner-1
                require_impedance_control: true,
                require_length_matching: true,
                require_diff_pair: false,
                max_stub_length: Some(Nm::from_mm(0.5)),   // short stubs only
                guard_trace_clearance: None,
            },
            SignalClass::Analog => SignalClassConstraints {
                min_trace_width: Nm::from_mm(0.2),        // 8 mil — low noise
                min_clearance: Nm::from_mm(0.3),           // 12 mil — isolation
                preferred_layers: Vec::new(),
                require_impedance_control: false,
                require_length_matching: false,
                require_diff_pair: false,
                max_stub_length: None,
                guard_trace_clearance: Some(Nm::from_mm(0.5)), // guard traces
            },
            SignalClass::Power => SignalClassConstraints {
                min_trace_width: Nm::from_mm(0.5),        // 20 mil — current capacity
                min_clearance: Nm::from_mm(0.2),           // 8 mil
                preferred_layers: Vec::new(),
                require_impedance_control: false,
                require_length_matching: false,
                require_diff_pair: false,
                max_stub_length: None,
                guard_trace_clearance: None,
            },
            SignalClass::Differential => SignalClassConstraints {
                min_trace_width: Nm::from_mm(0.127),      // 5 mil — impedance controlled
                min_clearance: Nm::from_mm(0.2),           // 8 mil
                preferred_layers: vec![0],                  // outer layer preferred
                require_impedance_control: true,
                require_length_matching: true,
                require_diff_pair: true,
                max_stub_length: Some(Nm::from_mm(0.3)),
                guard_trace_clearance: None,
            },
        }
    }
}

/// Per-signal-class constraint overrides.
///
/// When a net belongs to a signal class, these constraints override or
/// supplement the base [`DesignConstraints`]. Fields here represent
/// overrides — a routing engine should use the *stricter* of the base
/// constraint and the class constraint.
///
/// # Layer indices
///
/// `preferred_layers` uses `u8` layer indices (0 = top copper, 1 = inner-1, etc.)
/// to avoid depending on `cypcb-world`'s `Layer` enum.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SignalClassConstraints {
    /// Minimum trace width for this class.
    pub min_trace_width: Nm,
    /// Minimum clearance from other signals.
    pub min_clearance: Nm,
    /// Preferred routing layers (indices). Empty = no preference.
    pub preferred_layers: Vec<u8>,
    /// Whether impedance control is required.
    pub require_impedance_control: bool,
    /// Whether length matching is required within the net group.
    pub require_length_matching: bool,
    /// Whether this class requires differential pair routing.
    pub require_diff_pair: bool,
    /// Maximum stub length. `None` = no restriction.
    pub max_stub_length: Option<Nm>,
    /// Clearance for guard traces. `None` = no guard traces needed.
    pub guard_trace_clearance: Option<Nm>,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_all_variants_covered() {
        // Ensure default_constraints() works for every variant
        for class in SignalClass::ALL {
            let c = class.default_constraints();
            assert!(c.min_trace_width.raw() > 0, "{class:?} has zero trace width");
            assert!(c.min_clearance.raw() > 0, "{class:?} has zero clearance");
        }
    }

    #[test]
    fn test_power_has_wider_traces() {
        let digital = SignalClass::Digital.default_constraints();
        let power = SignalClass::Power.default_constraints();
        assert!(
            power.min_trace_width.raw() > digital.min_trace_width.raw(),
            "Power traces should be wider than digital"
        );
    }

    #[test]
    fn test_high_speed_requires_impedance() {
        let hs = SignalClass::HighSpeed.default_constraints();
        assert!(hs.require_impedance_control);
        assert!(hs.require_length_matching);
    }

    #[test]
    fn test_differential_requires_pair_routing() {
        let diff = SignalClass::Differential.default_constraints();
        assert!(diff.require_diff_pair);
        assert!(diff.require_impedance_control);
        assert!(diff.require_length_matching);
    }

    #[test]
    fn test_analog_has_guard_trace_clearance() {
        let analog = SignalClass::Analog.default_constraints();
        assert!(analog.guard_trace_clearance.is_some());
        assert!(analog.guard_trace_clearance.unwrap().raw() > 0);
    }

    #[test]
    fn test_high_speed_has_stub_limit() {
        let hs = SignalClass::HighSpeed.default_constraints();
        assert!(hs.max_stub_length.is_some());
        assert!(hs.max_stub_length.unwrap().raw() > 0);
    }

    #[test]
    fn test_signal_class_serde_roundtrip() {
        let class = SignalClass::Differential;
        let json = serde_json::to_string(&class).unwrap();
        let class2: SignalClass = serde_json::from_str(&json).unwrap();
        assert_eq!(class, class2);
    }

    #[test]
    fn test_signal_class_constraints_serde_roundtrip() {
        let sc = SignalClass::HighSpeed.default_constraints();
        let json = serde_json::to_string(&sc).unwrap();
        let sc2: SignalClassConstraints = serde_json::from_str(&json).unwrap();
        assert_eq!(sc, sc2);
    }

    #[test]
    fn test_analog_wider_clearance_than_digital() {
        let digital = SignalClass::Digital.default_constraints();
        let analog = SignalClass::Analog.default_constraints();
        assert!(
            analog.min_clearance.raw() > digital.min_clearance.raw(),
            "Analog should have wider clearance for noise isolation"
        );
    }
}

//! PCB layer stackup definitions.
//!
//! A [`Stackup`] describes the physical layer construction of a PCB:
//! copper layers, dielectric materials, solder mask, and silkscreen.
//! Factory methods provide common stackup configurations.

use cypcb_core::Nm;
use serde::{Deserialize, Serialize};

/// Type of layer in a PCB stackup.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum LayerType {
    /// Copper signal/routing layer.
    Signal,
    /// Copper plane layer (ground or power).
    Plane,
    /// Dielectric (insulating) material between copper layers.
    Dielectric,
    /// Solder mask layer.
    SolderMask,
    /// Silkscreen layer.
    Silkscreen,
}

impl LayerType {
    /// Whether this layer type contains copper.
    pub fn is_copper(self) -> bool {
        matches!(self, LayerType::Signal | LayerType::Plane)
    }
}

/// A single layer entry in a PCB stackup.
///
/// Describes one physical layer with its type, thickness, material
/// properties, and copper weight.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct LayerStackEntry {
    /// Human-readable name (e.g. "Top Copper", "Core", "Prepreg 1").
    pub name: String,
    /// Layer type.
    pub layer_type: LayerType,
    /// Layer thickness.
    pub thickness: Nm,
    /// Material name (e.g. "FR-4", "Copper", "LPI").
    pub material: String,
    /// Copper weight in oz/ft² × 10 (e.g. 10 = 1.0 oz). Zero for non-copper layers.
    pub copper_weight_oz_x10: u32,
    /// Dielectric constant (εr × 1000 for integer precision, e.g. 4500 = 4.500).
    /// Zero for copper layers.
    pub dielectric_constant_x1000: u32,
}

impl LayerStackEntry {
    /// Create a copper signal layer.
    pub fn signal(name: impl Into<String>, thickness: Nm, copper_oz_x10: u32) -> Self {
        Self {
            name: name.into(),
            layer_type: LayerType::Signal,
            thickness,
            material: "Copper".into(),
            copper_weight_oz_x10: copper_oz_x10,
            dielectric_constant_x1000: 0,
        }
    }

    /// Create a copper plane layer.
    pub fn plane(name: impl Into<String>, thickness: Nm, copper_oz_x10: u32) -> Self {
        Self {
            name: name.into(),
            layer_type: LayerType::Plane,
            thickness,
            material: "Copper".into(),
            copper_weight_oz_x10: copper_oz_x10,
            dielectric_constant_x1000: 0,
        }
    }

    /// Create a dielectric layer.
    pub fn dielectric(
        name: impl Into<String>,
        thickness: Nm,
        material: impl Into<String>,
        er_x1000: u32,
    ) -> Self {
        Self {
            name: name.into(),
            layer_type: LayerType::Dielectric,
            thickness,
            material: material.into(),
            copper_weight_oz_x10: 0,
            dielectric_constant_x1000: er_x1000,
        }
    }

    /// Create a solder mask layer.
    pub fn solder_mask(name: impl Into<String>, thickness: Nm) -> Self {
        Self {
            name: name.into(),
            layer_type: LayerType::SolderMask,
            thickness,
            material: "LPI".into(),
            copper_weight_oz_x10: 0,
            dielectric_constant_x1000: 3500, // typical LPI εr ≈ 3.5
        }
    }

    /// Create a silkscreen layer.
    pub fn silkscreen(name: impl Into<String>, thickness: Nm) -> Self {
        Self {
            name: name.into(),
            layer_type: LayerType::Silkscreen,
            thickness,
            material: "Epoxy Ink".into(),
            copper_weight_oz_x10: 0,
            dielectric_constant_x1000: 0,
        }
    }
}

/// Complete PCB layer stackup.
///
/// Describes the full physical construction from top to bottom. Layers are
/// ordered top-to-bottom: `layers[0]` is the topmost physical layer (typically
/// top silkscreen), `layers[last]` is the bottommost.
///
/// # Examples
///
/// ```
/// use cypcb_rules::Stackup;
///
/// let stackup = Stackup::two_layer_1oz();
/// assert_eq!(stackup.name, "2-Layer 1oz");
/// assert_eq!(stackup.copper_layer_count(), 2);
/// assert!(stackup.total_thickness.raw() > 0);
/// ```
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Stackup {
    /// Descriptive name for this stackup configuration.
    pub name: String,
    /// Ordered layers from top to bottom.
    pub layers: Vec<LayerStackEntry>,
    /// Total board thickness (sum of all layer thicknesses).
    pub total_thickness: Nm,
}

impl Stackup {
    /// Count the number of copper layers (Signal + Plane).
    pub fn copper_layer_count(&self) -> usize {
        self.layers.iter().filter(|l| l.layer_type.is_copper()).count()
    }

    /// Get all copper layer entries.
    pub fn copper_layers(&self) -> Vec<&LayerStackEntry> {
        self.layers.iter().filter(|l| l.layer_type.is_copper()).collect()
    }

    /// Get the total copper thickness.
    pub fn total_copper_thickness(&self) -> Nm {
        Nm(self.layers
            .iter()
            .filter(|l| l.layer_type.is_copper())
            .map(|l| l.thickness.raw())
            .sum())
    }

    /// Standard 2-layer, 1oz copper stackup.
    ///
    /// Total thickness: ~1.6mm (standard FR-4).
    /// Layers: Silkscreen / Mask / Top Cu / Core / Bottom Cu / Mask / Silkscreen
    pub fn two_layer_1oz() -> Self {
        let cu_thickness = Nm::from_mm(0.035); // 1oz copper ≈ 35µm
        let core_thickness = Nm::from_mm(1.5);  // FR-4 core
        let mask_thickness = Nm::from_mm(0.01);
        let silk_thickness = Nm::from_mm(0.005);

        let layers = vec![
            LayerStackEntry::silkscreen("Top Silkscreen", silk_thickness),
            LayerStackEntry::solder_mask("Top Solder Mask", mask_thickness),
            LayerStackEntry::signal("Top Copper", cu_thickness, 10),
            LayerStackEntry::dielectric("Core", core_thickness, "FR-4", 4500),
            LayerStackEntry::signal("Bottom Copper", cu_thickness, 10),
            LayerStackEntry::solder_mask("Bottom Solder Mask", mask_thickness),
            LayerStackEntry::silkscreen("Bottom Silkscreen", silk_thickness),
        ];

        let total = Nm(layers.iter().map(|l| l.thickness.raw()).sum());

        Self {
            name: "2-Layer 1oz".into(),
            layers,
            total_thickness: total,
        }
    }

    /// Standard 4-layer stackup.
    ///
    /// Signal / GND Plane / Power Plane / Signal.
    /// Total thickness: ~1.6mm.
    pub fn four_layer_standard() -> Self {
        let outer_cu = Nm::from_mm(0.035);  // 1oz
        let inner_cu = Nm::from_mm(0.035);  // 1oz inner
        let prepreg = Nm::from_mm(0.2);     // prepreg between outer and plane
        let core = Nm::from_mm(1.0);         // core between planes
        let mask_thickness = Nm::from_mm(0.01);
        let silk_thickness = Nm::from_mm(0.005);

        let layers = vec![
            LayerStackEntry::silkscreen("Top Silkscreen", silk_thickness),
            LayerStackEntry::solder_mask("Top Solder Mask", mask_thickness),
            LayerStackEntry::signal("Top Copper (L1)", outer_cu, 10),
            LayerStackEntry::dielectric("Prepreg 1", prepreg, "FR-4 Prepreg", 4200),
            LayerStackEntry::plane("GND Plane (L2)", inner_cu, 10),
            LayerStackEntry::dielectric("Core", core, "FR-4", 4500),
            LayerStackEntry::plane("Power Plane (L3)", inner_cu, 10),
            LayerStackEntry::dielectric("Prepreg 2", prepreg, "FR-4 Prepreg", 4200),
            LayerStackEntry::signal("Bottom Copper (L4)", outer_cu, 10),
            LayerStackEntry::solder_mask("Bottom Solder Mask", mask_thickness),
            LayerStackEntry::silkscreen("Bottom Silkscreen", silk_thickness),
        ];

        let total = Nm(layers.iter().map(|l| l.thickness.raw()).sum());

        Self {
            name: "4-Layer Standard".into(),
            layers,
            total_thickness: total,
        }
    }

    /// Standard 6-layer stackup.
    ///
    /// Signal / GND / Signal / Signal / Power / Signal.
    /// Total thickness: ~1.6mm.
    pub fn six_layer_standard() -> Self {
        let outer_cu = Nm::from_mm(0.035);
        let inner_cu = Nm::from_mm(0.018); // 0.5oz inner layers
        let prepreg_outer = Nm::from_mm(0.13);
        let core_1 = Nm::from_mm(0.36);
        let core_2 = Nm::from_mm(0.36);
        let prepreg_mid = Nm::from_mm(0.13);
        let mask_thickness = Nm::from_mm(0.01);
        let silk_thickness = Nm::from_mm(0.005);

        let layers = vec![
            LayerStackEntry::silkscreen("Top Silkscreen", silk_thickness),
            LayerStackEntry::solder_mask("Top Solder Mask", mask_thickness),
            LayerStackEntry::signal("Top Copper (L1)", outer_cu, 10),
            LayerStackEntry::dielectric("Prepreg 1", prepreg_outer, "FR-4 Prepreg", 4200),
            LayerStackEntry::plane("GND Plane (L2)", inner_cu, 5),
            LayerStackEntry::dielectric("Core 1", core_1, "FR-4", 4500),
            LayerStackEntry::signal("Inner Signal (L3)", inner_cu, 5),
            LayerStackEntry::dielectric("Prepreg 2", prepreg_mid, "FR-4 Prepreg", 4200),
            LayerStackEntry::signal("Inner Signal (L4)", inner_cu, 5),
            LayerStackEntry::dielectric("Core 2", core_2, "FR-4", 4500),
            LayerStackEntry::plane("Power Plane (L5)", inner_cu, 5),
            LayerStackEntry::dielectric("Prepreg 3", prepreg_outer, "FR-4 Prepreg", 4200),
            LayerStackEntry::signal("Bottom Copper (L6)", outer_cu, 10),
            LayerStackEntry::solder_mask("Bottom Solder Mask", mask_thickness),
            LayerStackEntry::silkscreen("Bottom Silkscreen", silk_thickness),
        ];

        let total = Nm(layers.iter().map(|l| l.thickness.raw()).sum());

        Self {
            name: "6-Layer Standard".into(),
            layers,
            total_thickness: total,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_two_layer_copper_count() {
        let s = Stackup::two_layer_1oz();
        assert_eq!(s.copper_layer_count(), 2);
    }

    #[test]
    fn test_four_layer_copper_count() {
        let s = Stackup::four_layer_standard();
        assert_eq!(s.copper_layer_count(), 4);
    }

    #[test]
    fn test_six_layer_copper_count() {
        let s = Stackup::six_layer_standard();
        assert_eq!(s.copper_layer_count(), 6);
    }

    #[test]
    fn test_two_layer_total_thickness_reasonable() {
        let s = Stackup::two_layer_1oz();
        let mm = s.total_thickness.to_mm();
        // Should be approximately 1.6mm
        assert!(mm > 1.4 && mm < 1.8, "2-layer thickness {mm}mm not in 1.4-1.8 range");
    }

    #[test]
    fn test_four_layer_total_thickness_reasonable() {
        let s = Stackup::four_layer_standard();
        let mm = s.total_thickness.to_mm();
        assert!(mm > 1.3 && mm < 1.9, "4-layer thickness {mm}mm not in 1.3-1.9 range");
    }

    #[test]
    fn test_six_layer_total_thickness_reasonable() {
        let s = Stackup::six_layer_standard();
        let mm = s.total_thickness.to_mm();
        assert!(mm > 1.0 && mm < 2.0, "6-layer thickness {mm}mm not in 1.0-2.0 range");
    }

    #[test]
    fn test_layer_type_is_copper() {
        assert!(LayerType::Signal.is_copper());
        assert!(LayerType::Plane.is_copper());
        assert!(!LayerType::Dielectric.is_copper());
        assert!(!LayerType::SolderMask.is_copper());
        assert!(!LayerType::Silkscreen.is_copper());
    }

    #[test]
    fn test_copper_layers_returns_only_copper() {
        let s = Stackup::four_layer_standard();
        let copper = s.copper_layers();
        assert_eq!(copper.len(), 4);
        for layer in &copper {
            assert!(layer.layer_type.is_copper());
        }
    }

    #[test]
    fn test_stackup_serde_roundtrip() {
        let s = Stackup::two_layer_1oz();
        let json = serde_json::to_string(&s).unwrap();
        let s2: Stackup = serde_json::from_str(&json).unwrap();
        assert_eq!(s, s2);
    }

    #[test]
    fn test_layer_entry_constructors() {
        let sig = LayerStackEntry::signal("Top", Nm::from_mm(0.035), 10);
        assert_eq!(sig.layer_type, LayerType::Signal);
        assert_eq!(sig.copper_weight_oz_x10, 10);

        let plane = LayerStackEntry::plane("GND", Nm::from_mm(0.035), 10);
        assert_eq!(plane.layer_type, LayerType::Plane);

        let di = LayerStackEntry::dielectric("Core", Nm::from_mm(1.0), "FR-4", 4500);
        assert_eq!(di.layer_type, LayerType::Dielectric);
        assert_eq!(di.dielectric_constant_x1000, 4500);
        assert_eq!(di.copper_weight_oz_x10, 0);

        let mask = LayerStackEntry::solder_mask("Top Mask", Nm::from_mm(0.01));
        assert_eq!(mask.layer_type, LayerType::SolderMask);

        let silk = LayerStackEntry::silkscreen("Top Silk", Nm::from_mm(0.005));
        assert_eq!(silk.layer_type, LayerType::Silkscreen);
    }
}

//! Routing rule trait for the A*-based autorouter.
//!
//! [`RoutingRuleSet`] is the primary interface between the design rules system
//! and the routing engine. It must be object-safe so it can be stored as
//! `dyn RoutingRuleSet` in the router.
//!
//! # Layer indices
//!
//! This module uses `u8` layer indices instead of importing `cypcb-world`'s
//! `Layer` enum, keeping `cypcb-rules` as a leaf crate. Convention:
//! - 0 = top copper
//! - 1 = inner-1
//! - N = bottom copper (where N = total_copper_layers - 1)

use crate::constraints::DesignConstraints;
use crate::signal_class::{SignalClass, SignalClassConstraints};
use cypcb_core::Nm;

/// Rule set interface for routing and DRC engines.
///
/// This trait is designed to be object-safe (`dyn RoutingRuleSet` compiles).
/// All methods take `&self` and return owned or reference types — no generics,
/// no `Self`-returning methods.
///
/// # For autorouter integration
///
/// The A* router uses:
/// - [`constraints_for_net`](RoutingRuleSet::constraints_for_net) to get per-net clearances and widths
/// - [`via_cost`](RoutingRuleSet::via_cost) to penalize layer transitions
/// - [`layer_change_cost`](RoutingRuleSet::layer_change_cost) to bias routing toward preferred layers
/// - [`clearance_between`](RoutingRuleSet::clearance_between) to check spacing between different nets
///
/// # Examples
///
/// ```
/// use cypcb_rules::{RoutingRuleSet, DesignConstraints, SignalClass, SignalClassConstraints};
/// use cypcb_core::Nm;
///
/// struct SimpleRules {
///     constraints: DesignConstraints,
/// }
///
/// impl RoutingRuleSet for SimpleRules {
///     fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
///         &self.constraints
///     }
///
///     fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
///         class.default_constraints()
///     }
///
///     fn via_cost(&self, _from_layer: u8, _to_layer: u8) -> f64 {
///         1.0
///     }
///
///     fn layer_change_cost(&self, _layer: u8) -> f64 {
///         0.5
///     }
///
///     fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
///         self.constraints.min_clearance
///     }
/// }
///
/// let rules = SimpleRules { constraints: DesignConstraints::default() };
/// let _: &dyn RoutingRuleSet = &rules; // object-safe
/// ```
pub trait RoutingRuleSet {
    /// Get the design constraints applicable to a specific net.
    ///
    /// For simple designs, this may return the same constraints for all nets.
    /// Advanced designs may have per-net overrides.
    fn constraints_for_net(&self, net_id: u32) -> &DesignConstraints;

    /// Get the signal-class-specific constraints.
    ///
    /// Returns an owned [`SignalClassConstraints`] because classes may be
    /// computed dynamically.
    fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints;

    /// Cost of placing a via transitioning between two layers.
    ///
    /// Higher values discourage the router from adding vias. Typical range:
    /// - 0.5–2.0 for standard vias
    /// - 5.0+ for blind/buried vias (more expensive to fabricate)
    /// - `f64::INFINITY` to prohibit a transition entirely
    fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64;

    /// Cost of routing on a specific layer.
    ///
    /// Used by the A* router to bias routing toward preferred layers.
    /// Lower values = preferred. Typical range: 0.1–2.0.
    fn layer_change_cost(&self, layer: u8) -> f64;

    /// Minimum clearance required between two specific nets.
    ///
    /// Allows net-pair-specific spacing rules (e.g. high-voltage isolation
    /// between power nets and signal nets).
    fn clearance_between(&self, net_a: u32, net_b: u32) -> Nm;
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Minimal implementation to verify the trait is object-safe and usable.
    struct TestRules {
        base: DesignConstraints,
    }

    impl TestRules {
        fn new() -> Self {
            Self {
                base: DesignConstraints::default(),
            }
        }
    }

    impl RoutingRuleSet for TestRules {
        fn constraints_for_net(&self, _net_id: u32) -> &DesignConstraints {
            &self.base
        }

        fn constraints_for_class(&self, class: SignalClass) -> SignalClassConstraints {
            class.default_constraints()
        }

        fn via_cost(&self, from_layer: u8, to_layer: u8) -> f64 {
            let span = (from_layer as i16 - to_layer as i16).unsigned_abs() as f64;
            span * 0.5
        }

        fn layer_change_cost(&self, layer: u8) -> f64 {
            if layer == 0 { 0.1 } else { 1.0 }
        }

        fn clearance_between(&self, _net_a: u32, _net_b: u32) -> Nm {
            self.base.min_clearance
        }
    }

    #[test]
    fn test_trait_object_safe() {
        let rules = TestRules::new();
        // This line proves object safety — if it compiles, dyn dispatch works.
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let c = dyn_rules.constraints_for_net(0);
        assert_eq!(c.min_clearance, DesignConstraints::default().min_clearance);
    }

    #[test]
    fn test_via_cost_scales_with_span() {
        let rules = TestRules::new();
        let cost_1 = rules.via_cost(0, 1);
        let cost_2 = rules.via_cost(0, 2);
        assert!(cost_2 > cost_1, "Multi-layer via should cost more");
    }

    #[test]
    fn test_layer_change_cost() {
        let rules = TestRules::new();
        assert!(rules.layer_change_cost(0) < rules.layer_change_cost(1));
    }

    #[test]
    fn test_clearance_between_returns_nm() {
        let rules = TestRules::new();
        let clearance = rules.clearance_between(1, 2);
        assert!(clearance.raw() > 0);
    }

    #[test]
    fn test_constraints_for_class() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;
        let power = dyn_rules.constraints_for_class(SignalClass::Power);
        let digital = dyn_rules.constraints_for_class(SignalClass::Digital);
        assert!(power.min_trace_width.raw() > digital.min_trace_width.raw());
    }

    #[test]
    fn test_dyn_dispatch_all_methods() {
        let rules = TestRules::new();
        let dyn_rules: &dyn RoutingRuleSet = &rules;

        // Exercise every trait method through dyn dispatch
        let _ = dyn_rules.constraints_for_net(42);
        let _ = dyn_rules.constraints_for_class(SignalClass::HighSpeed);
        let _ = dyn_rules.via_cost(0, 3);
        let _ = dyn_rules.layer_change_cost(1);
        let _ = dyn_rules.clearance_between(10, 20);
    }
}

//! PCB Design Rules Crate
//!
//! Provides the foundational types for PCB design rules, signal classification,
//! layer stackup definitions, and routing rule interfaces.
//!
//! This crate is a leaf dependency — it depends only on `cypcb-core` and has
//! no dependency on `cypcb-world`, `cypcb-drc`, or any other workspace crate.
//!
//! # Modules
//!
//! - [`constraints`]: PCB fabrication constraints ([`DesignConstraints`])
//! - [`signal_class`]: Signal classification and per-class overrides ([`SignalClass`])
//! - [`stackup`]: Layer stackup definitions ([`Stackup`], [`LayerStackEntry`])
//! - [`routing_rules`]: Routing rule trait for the autorouter ([`RoutingRuleSet`])
//!
//! # Usage
//!
//! ```
//! use cypcb_rules::{DesignConstraints, SignalClass, Stackup, RoutingRuleSet};
//!
//! // Get JLCPCB 2-layer defaults
//! let constraints = DesignConstraints::default();
//!
//! // Look up signal class constraints
//! let hs = SignalClass::HighSpeed.default_constraints();
//! assert!(hs.require_impedance_control);
//!
//! // Create a standard stackup
//! let stackup = Stackup::four_layer_standard();
//! assert_eq!(stackup.copper_layer_count(), 4);
//! ```

pub mod constraints;
pub mod routing_rules;
pub mod signal_class;
pub mod stackup;

// Re-export primary types at crate root.
pub use constraints::DesignConstraints;
pub use routing_rules::RoutingRuleSet;
pub use signal_class::{SignalClass, SignalClassConstraints};
pub use stackup::{LayerStackEntry, LayerType, Stackup};

